insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  3,
  $wyb$A scheduled Python bot that reads the last 24 hours of messages from your busiest Slack channels, uses your AI Builder credits to sort everything into what needs a decision today and what's just useful context, and DMs you the finished briefing every morning. No AI subscription of your own, and no code pasted from an AI chat window into your project — the starter code is real, already-tested Python you read, run, and extend yourself.$wyb$,
  $wyl$["Create a Slack app and scope its bot token to exactly what it needs", "Fetch and paginate channel history with the Slack Web API", "Separate “talk to an external API” code from pure, testable logic", "Design a prompt and parser that degrade gracefully instead of crashing on a bad AI reply", "Call AI through a shared, credit-metered gateway instead of your own API key", "Schedule a Python job to run unattended every morning"]$wyl$::jsonb,
  $sess${"model": "Claude Haiku 4.5 (via your AI Builder credits)", "totalTime": "110 min", "buildCount": 5, "whatYouNeed": ["Your AI Builder key (Credits page on your dashboard)", "Python 3.10+ installed", "A Slack workspace where you have permission to install apps (workspace admin access)"], "outcomes": ["Create a Slack app with exactly the bot permissions this project needs, no more", "Fetch and clean 24 hours of channel history using the real Slack Web API", "Turn raw chat noise into a two-section, AI-written briefing using your AI Builder credits", "Handle a malformed AI reply without crashing a job nobody is watching at 8am", "Schedule the whole pipeline to run automatically every morning"], "builds": [{"number": 1, "title": "Connect Slack and your AI Builder key", "time": "25 min", "description": "Before any code runs, Slack needs to know your bot exists and what it's allowed to do, and your project needs a way to spend AI Builder credits instead of your own API key.", "steps": [{"instruction": "Go to api.slack.com/apps → Create New App → From scratch. Name it (e.g. “Morning Briefing Bot”) and pick your workspace. Then go to OAuth & Permissions → Scopes → Bot Token Scopes and add: `channels:history`, `chat:write`, `users:read`, `im:write`. Click Install to Workspace, then copy the Bot User OAuth Token.", "verify": "Your Bot User OAuth Token starts with `xoxb-`, and OAuth & Permissions shows all four scopes listed under Bot Token Scopes."}, {"instruction": "In each Slack channel you want summarized, type `/invite @YourBotName` so the bot can read its history. Then click your profile photo → Copy member ID to get your own Slack user ID.", "verify": "Slack posts a system message in the channel confirming the bot joined, and your copied member ID starts with `U`."}, {"instruction": "Create a project folder. Inside it, create `requirements.txt` with this content, then run `pip install -r requirements.txt`:", "prompt": "slack_sdk\nrequests\npython-dotenv\nschedule\n", "verify": "pip install finishes with no errors, and `pip show slack_sdk` prints a real version number."}, {"instruction": "Create `sdt_ai.py` with this code — copy it exactly, you'll never edit it. This is the ONLY file that talks to the AI in this whole project:", "prompt": "\"\"\"\nSocial Dev AI Builder - your connection to the AI.\n\nYou do NOT need a ChatGPT Plus or Claude Pro subscription, and you do NOT\nneed an API key from any AI company. Your AI Builder credits come with\nyour course, and this file is what spends them.\n\nSETUP (you only do this once, ever):\n\n  1. Open your dashboard on socialdevtechnologies.com\n  2. Go to Credits, and click \"Copy my AI Builder key\"\n  3. In the same folder as this file, create a file named exactly:  .env\n  4. Put ONE line inside it - paste your own key after the = sign:\n\n         SDT_API_KEY=sdt_live_paste_your_own_key_here\n\n  5. Never share that key or put it on GitHub. It spends YOUR credits.\n\nThat's it. Every project in this course uses this same file.\n\"\"\"\n\nimport os\n\nimport requests\nfrom dotenv import load_dotenv\n\n# Reads the .env file sitting next to your project and loads SDT_API_KEY.\nload_dotenv()\n\n# Where your requests go. This is Social Dev's server, not an AI company's.\n# It checks your credits, then talks to the AI for you.\nGATEWAY_URL = \"https://qkrfpuckvymjpewcszgs.supabase.co/functions/v1/ai-gateway\"\n\n# This one is safe to have in the code - it is a public key that only\n# identifies the Social Dev project, not you. Your personal key is the\n# one in .env.\nPUBLIC_PROJECT_KEY = (\n    \"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.\"\n    \"eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InFrcmZwdWNrdnltanBld2NzemdzIiwicm9sZSI6ImFub24i\"\n    \"LCJpYXQiOjE3ODExMDk1MTQsImV4cCI6MjA5NjY4NTUxNH0.\"\n    \"Pv8MYd0zAQyk7tiConCLSUindSpMS83r4lY8dFU_5yE\"\n)\n\n\nclass AIError(Exception):\n    \"\"\"Something went wrong talking to the AI. The message explains what.\"\"\"\n\n\ndef ask_ai(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Send a question to the AI and get the answer back as text.\n\n        answer = ask_ai(\"Write a haiku about Lagos traffic\")\n        print(answer)\n\n    prompt      - what you want the AI to do. This is the important part.\n    system      - optional. Sets the AI's role, e.g. \"You are a careful editor.\"\n    max_tokens  - roughly how long the answer may be. 1000 is plenty for most.\n    project     - optional label so you can see usage per project later.\n\n    Returns the AI's answer as a plain string.\n    Raises AIError with a readable message if something is wrong.\n    \"\"\"\n    api_key = os.environ.get(\"SDT_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"No SDT_API_KEY found.\\n\"\n            \"Create a file named .env next to your code, containing:\\n\"\n            \"    SDT_API_KEY=sdt_live_your_key_here\\n\"\n            \"Copy your key from the Credits page on your dashboard.\"\n        )\n\n    payload = {\"prompt\": prompt, \"max_tokens\": max_tokens}\n    if system:\n        payload[\"system\"] = system\n    if project:\n        payload[\"project\"] = project\n\n    try:\n        response = requests.post(\n            GATEWAY_URL,\n            headers={\n                \"Authorization\": f\"Bearer {PUBLIC_PROJECT_KEY}\",\n                \"X-SDT-Key\": api_key,\n                \"Content-Type\": \"application/json\",\n            },\n            json=payload,\n            timeout=90,\n        )\n    except requests.RequestException:\n        raise AIError(\n            \"Could not reach the AI server. Check your internet connection \"\n            \"and try again. You were not charged any credits.\"\n        )\n\n    try:\n        data = response.json()\n    except ValueError:\n        raise AIError(f\"Unexpected reply from the AI server (status {response.status_code}).\")\n\n    # The server explains problems in plain English - show that message as-is\n    # rather than a status code, because it is written to be read by you.\n    if \"error\" in data:\n        raise AIError(data[\"error\"])\n\n    return data[\"text\"]\n\n\ndef ask_ai_detailed(prompt, **kwargs):\n    \"\"\"\n    Same as ask_ai, but returns the whole reply including how many credits\n    it cost. Useful while you are learning what things cost.\n\n        result = ask_ai_detailed(\"Summarise this\", max_tokens=200)\n        print(result[\"text\"])\n        print(\"cost:\", result[\"credits_charged\"], \"credits\")\n    \"\"\"\n    api_key = os.environ.get(\"SDT_API_KEY\")\n    if not api_key:\n        raise AIError(\"No SDT_API_KEY found. See the setup notes at the top of sdt_ai.py.\")\n\n    payload = {\"prompt\": prompt}\n    for name in (\"system\", \"max_tokens\", \"project\"):\n        if name in kwargs and kwargs[name] is not None:\n            payload[name] = kwargs[name]\n\n    response = requests.post(\n        GATEWAY_URL,\n        headers={\n            \"Authorization\": f\"Bearer {PUBLIC_PROJECT_KEY}\",\n            \"X-SDT-Key\": api_key,\n            \"Content-Type\": \"application/json\",\n        },\n        json=payload,\n        timeout=90,\n    )\n    data = response.json()\n    if \"error\" in data:\n        raise AIError(data[\"error\"])\n    return data\n\n\nif __name__ == \"__main__\":\n    # Running this file directly checks that your setup works.\n    print(\"Testing your AI Builder connection...\\n\")\n    try:\n        result = ask_ai_detailed(\"Say hello in exactly five words.\", max_tokens=50)\n        print(\"The AI said:\", result[\"text\"])\n        print(\"Credits used:\", result[\"credits_charged\"])\n        print(\"\\nYour setup works. You are ready to build.\")\n    except AIError as problem:\n        print(\"Setup problem:\\n\")\n        print(problem)\n", "verify": "Nothing to check yet — you'll test this file once your .env is filled in, in the next step."}, {"instruction": "Create `.env` in the same folder with this content, then replace the three placeholder values: your AI Builder key from the Credits page on your dashboard, your Slack bot token, and your Slack user ID.", "prompt": "# Copy this file to .env and paste your own key after the = sign.\n# Get your key from your dashboard: Credits -> Copy my AI Builder key\n# Never commit .env or share this key. It spends your credits.\n\nSDT_API_KEY=sdt_live_paste_your_own_key_here\n\n# Slack setup - see README.md for how to create your Slack app and\n# get these two values. Both are required before running main.py for real.\n# SLACK_BOT_TOKEN=xoxb-paste-your-bot-token-here\n# SLACK_USER_ID=U-paste-your-own-slack-user-id-here\n", "verify": "Run `python sdt_ai.py`. With all three values filled in correctly you'll see “The AI said: ...” followed by “Your setup works. You are ready to build.” If you instead see “No SDT_API_KEY found”, your .env file isn't being read — confirm it's named exactly `.env` and sits next to sdt_ai.py."}], "goFurther": "Add the `groups:history` scope too if you also want to summarize private channels the bot has been invited to."}, {"number": 2, "title": "Fetch and clean 24 hours of Slack messages", "time": "25 min", "description": "Slack's history endpoint hands back everything — join notices, edited-to-empty messages, bot chatter — mixed in with the conversation you actually want summarized. This build separates “talk to Slack” (needs a live workspace) from “make sense of what Slack sent back” (pure logic you can test right now with fake data).", "steps": [{"instruction": "Create `slack_client.py` with this code:", "prompt": "\"\"\"\nStep 1 of the Slack Morning Briefing Bot.\n\nThis file talks to Slack: pulling the last 24 hours of messages out of a\nchannel, and posting the finished briefing back as a DM.\n\nSlack's history endpoint hands back everything - join notices, bot\nmessages, edited-to-empty messages, thread replies mixed with top-level\nones - not just the conversation a human would read. The two jobs below\nare split on purpose: fetch_channel_history() needs a real bot token and\na live workspace, so it can't be checked here. filter_and_format_messages()\nis pure - no network, no token - so it's the one this file's self-test\nbelow actually exercises against realistic fake data.\n\"\"\"\n\nimport time\n\nfrom slack_sdk.errors import SlackApiError\n\n# Slack timestamps (\"ts\") are UNIX seconds as a string, e.g. \"1699999999.000100\".\nSECONDS_PER_DAY = 24 * 60 * 60\n\n\ndef fetch_channel_history(client, channel_id, hours=24):\n    \"\"\"\n    Downloads raw messages from one Slack channel over the last `hours` hours.\n\n    Returns the raw list of message dicts exactly as Slack sends them - see\n    https://api.slack.com/methods/conversations.history for the shape.\n    Requires a real bot token, so this function isn't part of the self-test\n    at the bottom of this file; filter_and_format_messages() is, since\n    that's where the logic actually worth testing lives.\n    \"\"\"\n    oldest = str(time.time() - hours * SECONDS_PER_DAY)\n    messages = []\n    cursor = None\n\n    # Slack paginates at 100 messages per page by default. A channel busier\n    # than that in 24h needs this cursor loop - skip it and you silently\n    # drop everything past the first page, which looks like \"it works\" in\n    # a quiet test channel and then quietly under-reports in a real one.\n    while True:\n        try:\n            response = client.conversations_history(\n                channel=channel_id,\n                oldest=oldest,\n                cursor=cursor,\n                limit=200,\n            )\n        except SlackApiError as error:\n            raise ValueError(\n                f\"Could not read that channel: {error.response['error']}.\\n\"\n                f\"Most common cause: the bot hasn't been invited to it yet - \"\n                f\"type /invite @YourBotName in that channel.\"\n            )\n\n        messages.extend(response[\"messages\"])\n        cursor = response.get(\"response_metadata\", {}).get(\"next_cursor\")\n        if not cursor:\n            break\n\n    return messages\n\n\ndef filter_and_format_messages(raw_messages, channel_name):\n    \"\"\"\n    Turns Slack's raw message list into clean \"user: text\" lines, oldest\n    first, or None if there was nothing worth reporting.\n\n        text = filter_and_format_messages(raw_messages, \"general\")\n\n    This drops the noise Slack mixes into channel history - join/leave\n    notices, topic changes, bot messages, messages edited down to nothing -\n    so you aren't paying AI credits to have the model read and discard it\n    for you. Real human messages have no \"subtype\" key at all; every kind\n    of noise Slack injects does.\n    \"\"\"\n    lines = []\n    for msg in raw_messages:\n        if msg.get(\"subtype\") is not None:\n            continue\n        text = msg.get(\"text\", \"\").strip()\n        if not text:\n            continue\n        user = msg.get(\"user\", \"someone\")\n        lines.append(f\"{user}: {text}\")\n\n    # Slack returns newest message first. Flip the order so the AI reads\n    # the conversation the way it actually happened - it matters for\n    # telling \"this got decided\" apart from \"this is still open\", which is\n    # exactly the judgment call the briefing is supposed to make for you.\n    lines.reverse()\n\n    if not lines:\n        return None\n\n    return f\"--- #{channel_name} ---\\n\" + \"\\n\".join(lines)\n\n\ndef post_dm(client, user_id, text):\n    \"\"\"\n    Sends `text` as a DM to `user_id`.\n\n    Slack's chat.postMessage needs a conversation ID, not a user ID -\n    conversations_open() finds (or silently creates, if this is the very\n    first message) the DM channel between the bot and that person.\n    \"\"\"\n    try:\n        dm = client.conversations_open(users=[user_id])\n        channel_id = dm[\"channel\"][\"id\"]\n        client.chat_postMessage(channel=channel_id, text=text)\n    except SlackApiError as error:\n        raise ValueError(f\"Could not send the DM: {error.response['error']}\")\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the filtering logic:\n    #     python slack_client.py\n    # This shape matches a real conversations.history response - see\n    # https://api.slack.com/methods/conversations.history#examples\n    fake_response = {\n        \"ok\": True,\n        \"messages\": [\n            {\"user\": \"U123\", \"text\": \"Ready for the 10am?\", \"ts\": \"1699999999.000100\"},\n            {\"user\": \"U456\", \"text\": \"\", \"ts\": \"1699999998.000100\"},\n            {\n                \"type\": \"message\",\n                \"subtype\": \"channel_join\",\n                \"user\": \"U789\",\n                \"text\": \"<@U789> has joined the channel\",\n                \"ts\": \"1699999997.000100\",\n            },\n            {\"user\": \"U123\", \"text\": \"Yep, see you there\", \"ts\": \"1699999996.000100\"},\n        ],\n    }\n\n    formatted = filter_and_format_messages(fake_response[\"messages\"], \"general\")\n    print(\"Normal channel history:\\n\")\n    print(formatted)\n\n    assert formatted is not None\n    assert \"has joined the channel\" not in formatted, \"join notices should be dropped\"\n    assert formatted.index(\"Yep, see you there\") < formatted.index(\"Ready for the 10am?\"), (\n        \"messages should end up oldest-first\"\n    )\n\n    # Break it on purpose: an empty channel (nobody posted in 24h, or every\n    # message in the window was noise). This is the exact input a quiet\n    # Slack channel produces on a Sunday morning - it must return None\n    # cleanly, not raise, so main.py can skip the channel instead of crashing\n    # the whole scheduled run over one quiet channel.\n    empty = filter_and_format_messages([], \"quiet-channel\")\n    print(\"\\nEmpty channel history:\", empty)\n    assert empty is None\n\n    noise_only = filter_and_format_messages(\n        [{\"type\": \"message\", \"subtype\": \"channel_join\", \"user\": \"U1\", \"text\": \"joined\", \"ts\": \"1\"}],\n        \"quiet-channel\",\n    )\n    assert noise_only is None, \"a channel with only noise should also come back as None\"\n\n    print(\"\\nAll slack_client.py self-tests passed.\")\n", "verify": "Run `python slack_client.py`. You'll see:\n\n```\nNormal channel history:\n\n--- #general ---\nU123: Yep, see you there\nU123: Ready for the 10am?\n\nEmpty channel history: None\n\nAll slack_client.py self-tests passed.\n```\n\nNo Slack token needed — this tests the filtering logic against fake message data shaped exactly like Slack's real API response."}], "goFurther": "Break it on purpose: change the fake `fake_response` in the self-test so every message has a `subtype` (as if the channel had nothing but join/leave notices for 24 hours). Run it again — `filter_and_format_messages` should still return `None` cleanly instead of crashing, which is exactly what protects a real quiet Sunday morning from breaking the whole scheduled run."}, {"number": 3, "title": "Turn messages into a prioritized briefing", "time": "25 min", "description": "This is where your AI Builder credits actually get spent — one call that reads the day's messages and sorts them into what needs attention versus what's just context.", "steps": [{"instruction": "Create `summarizer.py` with this code:", "prompt": "\"\"\"\nStep 2 of the Slack Morning Briefing Bot.\n\nTakes the cleaned message text from one or more channels (already produced\nby slack_client.filter_and_format_messages) and asks the AI to sort it into\nwhat needs attention today versus what's just useful context.\n\"\"\"\n\nfrom sdt_ai import ask_ai\n\n# Stop feeding messages to the AI after this many characters.\n#\n# A MONEY decision, not a technical one - same reasoning as article.py's\n# MAX_CHARACTERS in the Social Post Generator. Every character you send\n# costs credits, and a 24-hour dump from a few busy channels can run past\n# 20,000 characters on a heavy day. 8000 characters is roughly a full busy\n# day across 2-3 channels, or the last several hours of a very loud one -\n# enough for the AI to judge what's urgent without you paying to have it\n# re-read a full day of chatter to reach the same conclusion.\nMAX_CHARACTERS = 8000\n\n\ndef build_prompt(channel_texts):\n    \"\"\"\n    Combines the formatted text from every channel into one prompt.\n\n    channel_texts is a list of strings, each already formatted by\n    slack_client.filter_and_format_messages() as \"--- #channel ---\\\\n...\".\n    \"\"\"\n    combined = \"\\n\\n\".join(channel_texts)[:MAX_CHARACTERS]\n\n    return f\"\"\"You are preparing a morning briefing for someone who was away from\nSlack overnight. Below are yesterday's messages from their most important\nchannels.\n\nSort what matters into two sections:\n- TOP: things that need this person's attention or a decision today.\n  Be selective - if everything is \"top\", nothing is.\n- FYI: useful context, but nothing that needs action.\n\nFormat your answer EXACTLY like this, with the marker in square brackets\non its own line, then bullet points underneath it:\n\n[TOP]\n- first item\n- second item\n\n[FYI]\n- first item\n\nAfter the FYI section, write [END] on its own line.\n\nIf a section genuinely has nothing to report, write \"- Nothing to report\"\nunder it rather than skipping the heading - the person reading this expects\nto see both sections every single morning, not wonder if one went missing.\n\nDo not add any explanation, introduction or closing remark.\n\nMESSAGES:\n{combined}\"\"\"\n\n\ndef parse_briefing(reply):\n    \"\"\"\n    Turns the AI's marker-formatted reply into {\"TOP\": \"...\", \"FYI\": \"...\"}.\n\n    Returns {} if none of the expected markers showed up at all.\n\n    Markers instead of JSON for the same reason generator.py in the Social\n    Post Generator uses them: JSON breaks on a stray comma or a wrapping\n    code fence. That matters even more here, because this runs unattended\n    on a schedule at 8am - nobody is watching to hit \"regenerate\" the way\n    they would in an interactive app, so the parser has to survive a\n    slightly-off reply rather than take the whole job down with it.\n    \"\"\"\n    sections = {}\n    current_section = None\n    current_lines = []\n\n    for line in reply.splitlines():\n        stripped = line.strip()\n        marker = stripped.strip(\"[]\").upper()\n        is_marker = stripped.startswith(\"[\") and stripped.endswith(\"]\")\n\n        if is_marker and marker == \"END\":\n            break\n\n        if is_marker and marker in (\"TOP\", \"FYI\"):\n            if current_section:\n                sections[current_section] = \"\\n\".join(current_lines).strip()\n            current_section = marker\n            current_lines = []\n        elif current_section:\n            # The AI sometimes wraps its whole answer in ``` code fences -\n            # those aren't part of the briefing, so drop them.\n            if stripped.startswith(\"```\"):\n                continue\n            current_lines.append(line)\n\n    # Don't forget the last section - there's no marker after it to save it.\n    if current_section:\n        sections[current_section] = \"\\n\".join(current_lines).strip()\n\n    return sections\n\n\ndef format_dm_text(sections, header):\n    \"\"\"\n    Turns parsed {\"TOP\": ..., \"FYI\": ...} sections into the final Slack\n    mrkdwn message text, with a header line on top.\n\n    Uses \"Nothing to report\" as the fallback for a missing section rather\n    than leaving it out - main.py calls this only after parse_briefing()\n    already returned a non-empty dict, but the AI can still return just one\n    of the two sections, and a briefing silently missing \"FYI\" looks like a\n    bug, not a quiet night.\n    \"\"\"\n    return \"\\n\".join([\n        f\"*{header}*\",\n        \"\",\n        \"*Top priorities*\",\n        sections.get(\"TOP\", \"- Nothing to report\"),\n        \"\",\n        \"*FYI*\",\n        sections.get(\"FYI\", \"- Nothing to report\"),\n    ])\n\n\ndef summarize_briefing(channel_texts):\n    \"\"\"\n    The main function: give it a list of formatted channel texts, get back\n    the parsed sections dict.\n\n        sections = summarize_briefing([channel1_text, channel2_text])\n        print(sections[\"TOP\"])\n\n    Raises ValueError if there was nothing to summarize, or if the AI's\n    reply couldn't be parsed into the format this project depends on.\n    \"\"\"\n    if not channel_texts:\n        raise ValueError(\n            \"No messages to summarize - every channel came back empty.\\n\"\n            \"Nothing was sent to the AI, so no credits were used.\"\n        )\n\n    prompt = build_prompt(channel_texts)\n\n    # max_tokens caps how long (and how expensive) the AI's answer can be.\n    # 500 is generous for a two-section bullet list - a briefing longer\n    # than that has stopped being something you can read before your coffee\n    # finishes brewing, which defeats the point of the project.\n    reply = ask_ai(\n        prompt,\n        max_tokens=500,\n        project=\"slack-morning-briefing-bot\",\n    )\n\n    sections = parse_briefing(reply)\n\n    if not sections:\n        # This is the AI-reliability failure mode this project is most\n        # exposed to. The Streamlit apps in this course have a human\n        # sitting there to notice a bad reply and click \"generate\" again;\n        # a cron job at 8am does not. So instead of sending a DM full of\n        # unparsed prose, or letting main.py crash with a KeyError reading\n        # sections[\"TOP\"], we raise a clear, specific error that main.py\n        # can log and skip - the next scheduled run tries again on its own.\n        raise ValueError(\n            \"The AI replied, but not in the TOP/FYI format we asked for.\\n\"\n            \"This briefing was not sent - no partial or garbled DM went out.\\n\"\n            \"This usually fixes itself on the next scheduled run.\"\n        )\n\n    return sections\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing works:\n    #     python summarizer.py\n    good_reply = \"\"\"[TOP]\n- Client asked for the contract redline by noon\n- Deploy is blocked on a failing test - needs someone to look\n\n[FYI]\n- Design shared the new logo options in #general\n\n[END]\nLet me know if you'd like anything expanded!\"\"\"\n\n    sections = parse_briefing(good_reply)\n    print(\"Parsed a well-formed reply:\", list(sections.keys()))\n    assert sections[\"TOP\"].startswith(\"- Client asked\")\n    assert \"logo options\" in sections[\"FYI\"]\n    assert \"expanded\" not in sections[\"FYI\"], \"[END] should cut off the AI's sign-off\"\n\n    dm_text = format_dm_text(sections, \"Morning Briefing\")\n    print(\"\\n\" + dm_text)\n    assert \"Client asked\" in dm_text\n\n    # Break it on purpose: a malformed reply with no markers at all - the\n    # AI apologizing or chatting instead of following instructions. This is\n    # a real, observed failure mode, not a hypothetical one. parse_briefing\n    # must come back with {} rather than raise, so summarize_briefing() can\n    # turn that into the readable error above instead of a stack trace.\n    malformed_reply = \"Sure! Here's a summary of your Slack messages from last night, hope this helps.\"\n    empty_sections = parse_briefing(malformed_reply)\n    print(\"\\nParsed a malformed reply:\", empty_sections)\n    assert empty_sections == {}\n\n    # And the other edge case worth checking without spending real credits:\n    # a huge wall of text gets truncated before it's even built into a\n    # prompt, rather than silently sending (and paying for) all of it.\n    huge_input = [\"--- #general ---\\n\" + (\"spam \" * 5000)]\n    huge_prompt = build_prompt(huge_input)\n    assert len(huge_prompt) < len(huge_input[0]) + 2000, \"MAX_CHARACTERS should have capped this\"\n\n    print(\"\\nAll summarizer.py self-tests passed.\")\n", "verify": "Run `python summarizer.py`. You'll see a parsed TOP/FYI breakdown of a fake AI reply, a formatted DM preview, then:\n\n```\nParsed a malformed reply: {}\n\nAll summarizer.py self-tests passed.\n```\n\nNo AI Builder credits are spent by this test — it feeds parse_briefing() a hardcoded fake reply instead of calling ask_ai()."}], "goFurther": "Break it on purpose: this file's self-test already does it — look at `malformed_reply` and notice it has no `[TOP]` or `[FYI]` markers at all, just plain prose (a real, observed AI failure mode, not a hypothetical one). `parse_briefing()` returns `{}` instead of crashing, which is what lets `summarize_briefing()` raise one clear, readable error instead of main.py dying with a KeyError reading `sections[\"TOP\"]` at 8am with nobody watching."}, {"number": 4, "title": "Wire it together and schedule it", "time": "25 min", "description": "Connect the pieces into one script that runs the whole pipeline, then make sure it keeps running every morning without you.", "steps": [{"instruction": "Create `main.py` with this code, then replace the commented-out placeholders in `CHANNEL_IDS` near the top with your real channel IDs:", "prompt": "\"\"\"\nStep 3 of the Slack Morning Briefing Bot - the entrypoint that ties\neverything together and actually runs every morning.\n\nRun it once, right now, to check everything works:\n    python main.py\n\nRun it forever, sending itself at 08:00 every day:\n    python main.py --schedule\n\nOr skip the `schedule` package entirely and let your OS handle the timing -\nsee the README for the crontab (Mac/Linux) and Task Scheduler (Windows)\nequivalents. Both approaches call the same run_briefing() function; only\nwho presses the button (this file, or your OS) is different.\n\"\"\"\n\nimport os\nimport sys\nimport time\nfrom datetime import datetime\n\nimport schedule\nfrom dotenv import load_dotenv\nfrom slack_sdk import WebClient\n\nfrom sdt_ai import AIError\nfrom slack_client import fetch_channel_history, filter_and_format_messages, post_dm\nfrom summarizer import format_dm_text, summarize_briefing\n\nload_dotenv()\n\n# Fill these in with your own channel IDs before running this for real -\n# right-click a channel name in Slack > View channel details > scroll to\n# the bottom.\n#\n# Keep this list to 2-3 channels, not \"every channel I'm in\": each channel\n# adds to the character count summarizer.py sends to the AI (a cost you pay\n# every single morning, 365 mornings a year), and a briefing that digests\n# ten channels stops being something you actually read before coffee.\nCHANNEL_IDS = [\n    # \"C0123456789\",  # e.g. #general\n    # \"C9876543210\",  # e.g. #eng-team\n]\n\n\ndef run_briefing():\n    \"\"\"\n    Fetches, summarizes, and DMs one briefing. This is the whole program -\n    everything else in this file is either scheduling this function or\n    reading its own .env / CHANNEL_IDS setup.\n\n    Every failure path here prints a plain-English reason and returns\n    instead of raising, on purpose: this is meant to run unattended inside\n    cron or Task Scheduler, where an uncaught exception just looks like\n    \"nothing happened\" in a log nobody reads until the DM doesn't arrive.\n    \"\"\"\n    bot_token = os.environ.get(\"SLACK_BOT_TOKEN\")\n    user_id = os.environ.get(\"SLACK_USER_ID\")\n\n    if not bot_token or not user_id:\n        print(\n            \"Missing SLACK_BOT_TOKEN or SLACK_USER_ID.\\n\"\n            \"Copy .env.example to .env, uncomment those two lines, and fill \"\n            \"them in - see README.md for where to find each value.\"\n        )\n        return\n\n    if not CHANNEL_IDS:\n        print(\"CHANNEL_IDS is empty. Add at least one channel ID near the top of main.py.\")\n        return\n\n    client = WebClient(token=bot_token)\n\n    channel_texts = []\n    for channel_id in CHANNEL_IDS:\n        try:\n            info = client.conversations_info(channel=channel_id)\n            channel_name = info[\"channel\"][\"name\"]\n        except Exception:\n            # A bad or renamed channel ID shouldn't take the whole briefing\n            # down - fall back to the raw ID so the summary still labels\n            # this channel's messages with something, and keep going.\n            channel_name = channel_id\n\n        try:\n            raw_messages = fetch_channel_history(client, channel_id, hours=24)\n        except ValueError as problem:\n            print(f\"Skipping #{channel_name}: {problem}\")\n            continue\n\n        formatted = filter_and_format_messages(raw_messages, channel_name)\n        if formatted:\n            channel_texts.append(formatted)\n        else:\n            print(f\"#{channel_name} had nothing worth reporting in the last 24h.\")\n\n    try:\n        sections = summarize_briefing(channel_texts)\n    except (ValueError, AIError) as problem:\n        print(f\"Briefing not sent: {problem}\")\n        return\n\n    today = datetime.now().strftime(\"%A, %B %d\")\n    text = format_dm_text(sections, f\"\\U0001F305 Morning Briefing — {today}\")\n\n    try:\n        post_dm(client, user_id, text)\n    except ValueError as problem:\n        print(f\"Could not deliver the briefing: {problem}\")\n        return\n\n    print(\"Briefing sent!\")\n\n\nif __name__ == \"__main__\":\n    if \"--schedule\" in sys.argv:\n        # The `schedule` package keeps this process running and calls\n        # run_briefing() every day at 08:00 in your machine's local time.\n        # This only works while the process itself stays alive - if your\n        # laptop sleeps or you close the terminal, nothing runs. Cron /\n        # Task Scheduler (see README) survive both; this is the quick way\n        # to test the daily timing without setting either up first.\n        schedule.every().day.at(\"08:00\").do(run_briefing)\n        print(\"Scheduled for 08:00 daily. Leave this running... (Ctrl+C to stop)\")\n        while True:\n            schedule.run_pending()\n            time.sleep(30)\n    else:\n        # No flag: run the briefing once, immediately. This is how you\n        # test the whole pipeline before trusting it to a schedule you\n        # won't be watching.\n        run_briefing()\n", "verify": "Run `python main.py`. Within about 20 seconds you should get a real Slack DM titled “🌅 Morning Briefing — <today's date>” with Top priorities / FYI sections, and “Briefing sent!” printed in your console. If SLACK_BOT_TOKEN, SLACK_USER_ID, or CHANNEL_IDS is missing, main.py prints exactly which one instead of attempting the run."}, {"instruction": "Decide how this runs every morning without your laptop staying on: crontab on Mac/Linux, or Task Scheduler on Windows (both documented in README.md). Set one up pointing at your virtual environment's Python, not just `python`.", "verify": "Run the exact scheduled command by hand in a terminal and confirm a DM arrives, before trusting it to actually run unattended at 8am."}], "goFurther": "Deploy main.py to a small always-on host (Railway, Render, or a $5 VPS) with its own scheduled-task feature, so the briefing still arrives on a morning your laptop is closed."}, {"number": 5, "phaseLabel": "🎯 Challenge", "title": "Challenge: add a third briefing section", "time": "15 min", "description": "Anyone can copy-paste working code. The real test is whether you understand the marker-parsing pattern well enough to extend it yourself — without breaking the malformed-reply protection you just relied on in Build 3.", "steps": [{"instruction": "Add a third section, `WINS`, for good news from the last 24 hours (a shipped fix, a closed deal, positive feedback). You'll need to: (1) mention `[WINS]` in the prompt inside `build_prompt()`, (2) add `\"WINS\"` to the tuple of recognized markers inside `parse_briefing()`, and (3) add a `*Wins*` block to `format_dm_text()`. Start from this skeleton:", "prompt": "# In build_prompt(), add a third instruction alongside TOP and FYI:\n#   - WINS: good news from the last 24 hours - a shipped fix, a closed\n#     deal, positive feedback. Nothing to report is a valid answer here too.\n#\n# In parse_briefing(), the recognized-marker check currently reads:\n#   if is_marker and marker in (\"TOP\", \"FYI\"):\n# TODO: add \"WINS\" to that tuple - one word, that's the whole fix here.\n#\n# In format_dm_text(), add a third block the same shape as the other two:\n#   lines.append(\"*Wins*\")\n#   lines.append(sections.get(\"WINS\", \"- Nothing to report\"))\n#\n# TODO: write the actual code for all three changes above.", "verify": "Feed parse_briefing() this exact fake reply:\n\n`\"[TOP]\\n- a\\n[WINS]\\n- shipped a fix\\n[FYI]\\n- b\\n[END]\"`\n\nThe returned dict must have `len(sections) == 3` and `sections[\"WINS\"] == \"- shipped a fix\"`. Before your fix, `len(sections)` is 2 and the WINS lines get silently absorbed into FYI — that's the bug you're fixing."}]}], "portfolio": "You built a bot that reads your busiest Slack channels overnight and DMs you a prioritized briefing every morning — real Slack API integration plus a production-style pattern for handling unreliable AI output on an unattended schedule. Take a screenshot of a real briefing DM and add “Slack Morning Briefing Bot” to your build portfolio with a one-line description.", "portfolioPrompt": "I just built a Slack bot that reads the last 24 hours of messages from my key channels, uses AI to sort everything into a Top Priorities section and an FYI section, and DMs me the finished briefing every morning on a schedule.\n\nHelp me write:\n1. A 2-3 sentence project description for my portfolio site\n2. A short LinkedIn post announcing it\n3. Three resume-style bullet points describing what I built and the skills it shows"}$sess$::jsonb,
